import numpy as np
import pandas as pd

def metric(data: pd.DataFrame) -> float:
    def ttb_predict(row):
        a = row['option_a_ratings']
        b = row['option_b_ratings']
        for i in range(len(a)):
            if a[i] > b[i]:
                return 0
            elif a[i] < b[i]:
                return 1
        return 0.5

    ttb_choices = data.apply(ttb_predict, axis=1)
    matches = (data['response'] == ttb_choices)
    return float(matches.mean())

